<?php
require __DIR__.'/bootstrap.php';require __DIR__.'/capture-core.php';require_once __DIR__.'/email-core.php';
if(!authorized()){http_response_code(403);exit('Administrator access required.');}$_SESSION['last_seen']=time();$error='';$notice='';$db=db();
function h($s): string {return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
function token_field(): string {return '<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'">';}
try {
 $cfg=qm_config();
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??'')))throw new CaptureError('Invalid request token. Reload.');
  $db->beginTransaction();[$revision,$state]=cap_lock($db);$action=$_POST['action']??'';
  if($action==='queue'){
   if(!isset($_POST['confirm']))throw new CaptureError('Confirm the selected invitations before queueing.');
   $ids=($_POST['scope']??'')==='all'?array_column($state['owners'],'id'):[(int)($_POST['ownerId']??0)];
   $result=qm_queue_invites($db,$state,(string)($_POST['purpose']??''),$ids,isset($_POST['resend']),$config['admin_username']);cap_store($db,$revision,$state);$notice=$result['queued'].' queued; '.$result['skipped'].' skipped. The worker sends queued messages.';
  }elseif($action==='test'){
   $email=trim((string)($_POST['recipient']??''));qm_add($db,$cfg,'test',$email,['subject'=>'Quorum SMTP delivery test','body'=>"This is a test from Quorum using vote@gemb.co.za.\nNo owner invitation or registration data is included.\n"]);$notice='Test queued. Run the worker, then check the recipient inbox and spam folder.';
  }elseif($action==='retry'){
   $s=$db->prepare('SELECT * FROM quorum_mail_queue WHERE id=? FOR UPDATE');$s->execute([(int)($_POST['id']??0)]);$q=$s->fetch(PDO::FETCH_ASSOC);
   if(!$q||!in_array($q['status'],['failed','uncertain'],true)||!$q['payload']||(int)$q['attempts']>=3||!isset($_POST['confirm_retry']))throw new CaptureError('Retry unavailable or acknowledgement missing. At most three attempts per message.');
   if($q['kind']==='otp')throw new CaptureError('Ask the owner to request a fresh login code instead.');
   $db->prepare("UPDATE quorum_mail_queue SET status='queued',error_code=NULL,updated_at=? WHERE id=?")->execute([time(),$q['id']]);$notice='Retry queued with the same message ID. A previous uncertain attempt may already have reached the mailbox.';
  }else throw new CaptureError('Unknown operation.');
  $db->commit();
 }
 $db->beginTransaction();[, $state]=cap_lock($db);$state=qm_sync_flags($db,$state);$db->commit();
 $messages=$db->query('SELECT id,owner_id,kind,recipient,status,attempts,updated_at,error_code FROM quorum_mail_queue ORDER BY id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);
 $counts=$db->query('SELECT status,COUNT(*) n FROM quorum_mail_queue GROUP BY status')->fetchAll(PDO::FETCH_ASSOC);
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e instanceof CaptureError||$e instanceof RuntimeException?$e->getMessage():'Email management unavailable. Check server logs.';error_log('Quorum email management: '.$e->getMessage());$state=$state??['owners'=>[]];$messages=$messages??[];$counts=$counts??[];}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quorum · Invitations &amp; email</title><style>body{font:15px system-ui;background:#f4f7f5;color:#174333;max-width:1050px;margin:auto;padding:20px}section{background:white;padding:20px;margin:18px 0;border:1px solid #d5e0d8;border-radius:10px}label{display:block;margin:12px 0 5px}input:not([type=checkbox]),select{font:inherit;padding:10px;width:100%;max-width:650px}button{padding:12px;background:#174c3e;color:white;border:0;border-radius:6px;margin:12px 0;cursor:pointer}table{width:100%;border-collapse:collapse}th,td{padding:8px;text-align:left;border-bottom:1px solid #ddd}.error{background:#ffe0d9;padding:16px}.notice{background:#fff1ce;padding:16px}a{color:#174c3e}.table{overflow:auto}</style></head><body>
<a href="index.php">← Administrator workspace</a><h1>Invitations &amp; email</h1><p>Sender: vote@gemb.co.za · mail.gemb.co.za · encrypted SMTP port 465</p>
<?php if($error): ?><p class="error" role="alert"><?=h($error)?></p><?php endif ?><?php if($notice): ?><p class="notice" role="status"><?=h($notice)?></p><?php endif ?>
<p>Sending <?=!empty($cfg['enabled'])?'enabled':'disabled in private mail.php'?>. Limit <?=h($cfg['max_per_hour']??'not configured')?> attempts/hour. Confirm your hosting allowance before bulk use. Login-code emails have queue priority.</p>
<section><h2>1. Test delivery first</h2><form method="post"><?=token_field()?><input type="hidden" name="action" value="test"><label for="test-address">Your test recipient address</label><input id="test-address" type="email" name="recipient" required><button>Queue one test email</button></form><p>After queueing, run send-mail.php in cPanel Terminal. SMTP acceptance does not prove inbox delivery; check the actual mailbox.</p></section>
<section><h2>2. Queue owner invitations</h2><p><?=count(array_filter($state['owners'],fn($o)=>cap_eligible($o)))?> entitled owners; <?=count(array_filter($state['owners'],fn($o)=>!empty($o['registered'])))?> real owner registrations.</p>
<form method="post"><?=token_field()?><input type="hidden" name="action" value="queue"><label for="purpose">Invitation type</label><select id="purpose" name="purpose"><option value="registration">Register: create owner username/password</option><option value="meeting" <?=($_GET["purpose"]??"")==="meeting"?"selected":""?>>Meeting: sign in to vote (registered owners; voting must be open)</option><option value="reset">Reset registration (one existing owner only)</option></select><label for="scope">Recipients</label><select id="scope" name="scope"><option value="one">One selected owner</option><option value="all">All qualifying owners</option></select><label for="ownerId">Selected property / owner</label><select id="ownerId" name="ownerId"><?php foreach($state['owners'] as $o): ?><option value="<?=h($o['id'])?>"><?=h($o['unit'].' — '.$o['name'].' — '.$o['email'])?></option><?php endforeach ?></select><label><input type="checkbox" name="resend"> Replace existing links and send again (older links stop working)</label><label><input type="checkbox" name="confirm" required> I approve emailing the selected qualifying owners.</label><button>Queue invitations</button></form><p>Existing valid invitations are skipped unless replacement is selected. Registration skips already registered accounts. Meeting invitations require a real registered account. The main browser preview's sample registrations do not qualify.</p></section>
<section><h2>Sending status</h2><p><?php foreach($counts as $c)echo h($c['status'].': '.$c['n']).' · '; ?></p><p>sent = SMTP accepted; uncertain = inspect before retrying. Recipient addresses are individual; no owner list is shared with recipients.</p><div class="table"><table><thead><tr><th>ID</th><th>Recipient / type</th><th>Status</th><th>UTC</th><th>Action</th></tr></thead><tbody><?php foreach($messages as $m): ?><tr><td><?=h($m['id'])?></td><td><?=h($m['recipient'])?><br><?=h($m['kind'])?></td><td><?=h($m['status'])?> · <?=h($m['attempts'])?> attempts<br><?=h($m['error_code']??'')?></td><td><?=h(gmdate('Y-m-d H:i:s',(int)$m['updated_at']))?></td><td><?php if(in_array($m['status'],['failed','uncertain'],true)&&$m['kind']!=='otp'&&(int)$m['attempts']<3): ?><form method="post"><?=token_field()?><input type="hidden" name="action" value="retry"><input type="hidden" name="id" value="<?=h($m['id'])?>"><label><input type="checkbox" name="confirm_retry" required> A duplicate email may result.</label><button>Retry</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section></body></html>
